data.query:
query Shipment($where: ShipmentWhereInput, $orderBy: [ShipmentOrderByInput!], $first: Int, $after: String) {
  shipment(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        commercialInvoiceNumber
      }
    }
  }
}

data.mutation:
mutation data($payload: [GenerateSequenceNumberPayloadInput!]!){
  generateSequenceNumber(payload: $payload){
    id
    key
    value
    sequenceId
  }
}

